<div class="panel attention-panel" data-reveal><div class="panel-heading"><div><span class="eyebrow">NECESITA TU ATENCIÓN</span><h2>Pendientes del equipo</h2></div><span class="attention-count"><?= count($alerts) ?></span></div><?php foreach($alerts as $alert): ?><a class="attention-item" href="<?= e(url($alert['url'])) ?>"><span class="attention-icon"><?= icon($alert['icon'],21) ?></span><span><strong><?= e($alert['title']) ?></strong><small><?= e($alert['description']) ?></small></span><?= icon('arrow',16) ?></a><?php endforeach; ?><?php if(!$alerts): ?><div class="empty"><?= icon('check',35) ?><h3>Todo en orden por aquí.</h3><p>No hay alertas que requieran tu atención con estos filtros.</p></div><?php endif; ?></div>
